effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    vec2 g = fract(acScreenNorm*size);
    float gx = min(g.x, 1.0-g.x);
    float gy = min(g.y, 1.0-g.y);
    float line = 1.0 - smoothstep(0.0, width, min(gx,gy));
    vec3 outc = mix(c, color.rgb, line*amount);
    gl_FragColor = vec4(outc,1.0)*src.a;
}
